    { "@type": "Question", "name": "How much does land clearing cost per acre in Ohio?", "acceptedAnswer": { "@type": "Answer", "text": "Land clearing in NE Ohio runs $1,500–$20,000+ per acre depending on density. Light brush is $1,500–$3,000/acre; medium-density wooded lots are $3,000–$5,000/acre; heavy mature wooded lots can exceed $20,000/acre with full haul-off. Selective clearing (preserving marked trees) typically costs more than full clearing. See the Tree Service Cost Guide for additional context." } },
    { "@type": "Question", "name": "Do I need a permit to clear my land in Geauga County?", "acceptedAnswer": { "@type": "Answer", "text": "Geauga County generally follows standard private-property rules — no routine permit for clearing on private residential property. However, large-scale clearing that changes land use (residential to agricultural, agricultural to commercial) may trigger a zoning review at the township level. Wetland delineation may apply near streams or seasonal water features. Roubic confirms permit and zoning requirements as part of every clearing estimate." } },
    { "@type": "Question", "name": "What's the difference between brush clearing and full land clearing?", "acceptedAnswer": { "@type": "Answer", "text": "Brush clearing targets the understory — small-diameter trees (under about 6 inches DBH), saplings, vines, and invasive shrubs — without removing mature canopy trees. Full land clearing removes everything, including stumps, with final grading. Brush clearing is faster and cheaper; full clearing prepares the site for construction or major land-use change." } },
    { "@type": "Question", "name": "Can you clear land in winter?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — winter is often the best time to clear in NE Ohio. Frozen ground minimizes soil compaction and rut damage from heavy equipment, and leaves-off visibility makes boundary markers and preserved trees much easier to see. We clear from October through March routinely. Spring and wet conditions are poor timing because of equipment ruts." } },
    { "@type": "Question", "name": "Do you offer forestry mulching?", "acceptedAnswer": { "@type": "Answer", "text": "No — Roubic does not currently offer forestry mulching as a clearing method. Our land clearing service uses traditional cut-and-haul or selective clearing approaches with skid steer, track loader, and chipper equipment. If forestry mulching is specifically required for your project, we can recommend a partner contractor who specializes in that method." } },
    { "@type": "Question", "name": "How long does land clearing take?", "acceptedAnswer": { "@type": "Answer", "text": "Light brush on a 1-acre lot: typically 1–2 days. Medium-density 1–2 acre lots: 2–4 days. Heavy wooded 1-acre lots: 3–5 days, sometimes longer with haul-off. Multi-acre clearing scales roughly linearly. Permit timelines (when applicable) can add 2–6 weeks to the start date." } },
    { "@type": "Question", "name": "Does clearing include stump grinding and debris haul-off?", "acceptedAnswer": { "@type": "Answer", "text": "On a full clear, yes — below-grade stump grinding is included in the contract, and debris is hauled off to a licensed disposal facility as the standard finish. If you'd rather keep the chips, we drop them on-site instead. Either way it's coordinated with a final-grade pass under one contract, so you're not booking clearing, grinding, and grade as three separate mobilizations." } }
